/**
 * @description What's implemented & usage, and Who uses Integration Hub (How To tab, admins only). One scan returns the
 * raw facts the screen needs: per Apex class and trigger its name, characters (comments not counted), whether it is a
 * test, whether it calls IntegrationHub.publish and with which event keys, and which plugged-in class names a test
 * mentions; the events; the connections with an Auth Class; the implementers of the Integration Hub interfaces; transaction counts per event and Integration
 * Hub background job counts of the last 24 hours; the Integration Hub objects and their custom field counts. Class
 * and trigger code is read in SOQL for-loop chunks and never kept or returned. The screen (c/ihUsage) groups it and
 * shows only Integration Hub and the code that uses it.
 * @group Integration Hub
 */
public with sharing class IntegrationHubUsage {

    /** @description Apex characters an org may hold (non-test code, comments not counted). */
    public static final Integer APEX_LIMIT = 6000000;
    /** @description The classes that run as background jobs. */
    public static final List<String> JOB_CLASSES = new List<String>{
        'IntegrationHubSender', 'IntegrationHubBusiness', 'IntegrationHubMaintenance', 'IntegrationHubAutoRetry'
    };
    /** @description The Integration Hub objects. */
    public static final List<String> OBJECTS = new List<String>{
        'IH_Connection__c', 'IH_Event__c', 'IH_Transaction__c', 'IH_Attempt__c', 'IH_Settings__c'
    };
    /** @description The Integration Hub interfaces a class of the org can implement (with and without the outer class). */
    public static final List<String> INTERFACES = new List<String>{
        'IntegrationHub.IPayloadBuilder', 'IntegrationHub.IResponseHandler', 'IntegrationHub.IInboundHandler',
        'IntegrationHub.IConnectionAuth', 'IPayloadBuilder', 'IResponseHandler', 'IInboundHandler', 'IConnectionAuth'
    };
    /** @description Kind of a code row read from ApexClass. */
    public static final String KIND_CLASS = 'Class';
    /** @description Kind of a code row read from ApexTrigger. */
    public static final String KIND_TRIGGER = 'Trigger';

    private static final String PUBLISH = 'IntegrationHub.publish';
    private static final Integer SNIPPET = 300;
    private static final Pattern KEY_LITERAL = Pattern.compile('(?i)^IntegrationHub\\.publish\\s*\\(\\s*\'([^\'\\\\]+)\'');
    private static final String HIDDEN_BODY = '(hidden)';
    /** Built in two parts so this class's own code does not look like a test class to the scan. */
    private static final String TEST_MARK = '@' + 'IsTest';

    /**
     * @description One Apex class or trigger of the org: names and numbers only, never its code.
     */
    public class CodeRow {
        /** @description Class or Trigger. */
        @AuraEnabled
        public String kind;
        /** @description Class or trigger name. */
        @AuraEnabled
        public String name;
        /** @description Characters, comments not counted. */
        @AuraEnabled
        public Integer chars;
        /** @description True for a test class. */
        @AuraEnabled
        public Boolean isTest = false;
        /** @description True when its code contains IntegrationHub.publish (tests excluded). */
        @AuraEnabled
        public Boolean publishes = false;
        /** @description Event keys written as text in its publish calls. */
        @AuraEnabled
        public List<String> keys = new List<String>();
        /** @description Test classes only: the plugged-in class names its code mentions. */
        @AuraEnabled
        public List<String> mentions = new List<String>();
    }

    /**
     * @description A count of the last 24 hours: transactions per event and status, or jobs per class and status.
     */
    public class CountRow {
        /** @description Event Id or Apex class Id. */
        @AuraEnabled
        public String key;
        /** @description Transaction or job status. */
        @AuraEnabled
        public String status;
        /** @description How many. */
        @AuraEnabled
        public Integer count;
        /** @description Latest one (transaction created, job completed). */
        @AuraEnabled
        public Datetime lastAt;
    }

    /**
     * @description An Integration Hub object and its custom field count.
     */
    public class ObjectRow {
        /** @description API name. */
        @AuraEnabled
        public String name;
        /** @description Custom fields. */
        @AuraEnabled
        public Integer customFields;
    }

    /**
     * @description Result of one scan. Readers get admin = false and a message; the lists are empty.
     */
    public class Scan {
        /** @description True when the user is an Integration Hub admin. */
        @AuraEnabled
        public Boolean admin = false;
        /** @description Note for the screen. */
        @AuraEnabled
        public String message;
        /** @description When the scan ran. */
        @AuraEnabled
        public Datetime scannedAt = System.now();
        /** @description The Apex character limit (6,000,000). */
        @AuraEnabled
        public Integer apexLimit = APEX_LIMIT;
        /** @description Apex classes and triggers of the org (not managed), plus Integration Hub ones in any namespace. */
        @AuraEnabled
        public List<CodeRow> code = new List<CodeRow>();
        /** @description Events (Id, key, direction, active, connection, class fields, options). */
        @AuraEnabled
        public List<IH_Event__c> events = new List<IH_Event__c>();
        /** @description Connections with an Auth Class (Id, Name, Connection_Type__c, Auth_Class__c). */
        @AuraEnabled
        public List<IH_Connection__c> connections = new List<IH_Connection__c>();
        /** @description Concrete classes of the org implementing an Integration Hub interface (ClassName, InterfaceName). */
        @AuraEnabled
        public List<SObject> implementers = new List<SObject>();
        /** @description Transactions of the last 24 hours per event Id and status. */
        @AuraEnabled
        public List<CountRow> transactions = new List<CountRow>();
        /** @description The background job classes found (Id, Name). */
        @AuraEnabled
        public List<SObject> jobClasses = new List<SObject>();
        /** @description Jobs of the last 24 hours per class Id and status. */
        @AuraEnabled
        public List<CountRow> jobs = new List<CountRow>();
        /** @description The Integration Hub objects. */
        @AuraEnabled
        public List<ObjectRow> objects = new List<ObjectRow>();
    }

    /**
     * @description Scans Integration Hub and the code that uses it. Admins only: readers get admin = false and a note.
     * @return the scan
     */
    @AuraEnabled(cacheable=false)
    public static Scan scan() {
        Scan result = new Scan();
        result.admin = IntegrationHubPreview.isAdmin();
        if (!result.admin) {
            result.message = 'The live numbers are for Integration Hub admins. The tables describe every part.';
            return result;
        }
        Datetime since = System.now().addHours(-24);
        result.events = (List<IH_Event__c>) IntegrationHubData.query('SELECT Id, Event_Key__c, Direction__c, Active__c, '
            + 'Connection__c, Connection__r.Name, Payload_Source__c, Payload_Class__c, Response_Handler_Class__c, '
            + 'Business_Data_In_Response__c, Handler_Class__c, Expects_Callback__c FROM IH_Event__c ORDER BY Event_Key__c '
            + 'LIMIT 2000', null);
        result.connections = (List<IH_Connection__c>) IntegrationHubData.query('SELECT Id, Name, Connection_Type__c, '
            + 'Auth_Class__c FROM IH_Connection__c WHERE Auth_Class__c != null ORDER BY Name LIMIT 2000', null);
        result.implementers = implementers();
        result.code = new Elevated(pluginNames(result)).scanCode();
        result.transactions = counts(IntegrationHubData.query('SELECT Event__c k, Status__c st, COUNT(Id) n, '
            + 'MAX(CreatedDate) lastAt FROM IH_Transaction__c WHERE CreatedDate >= :since AND Event__c != null '
            + 'GROUP BY Event__c, Status__c', new Map<String, Object>{ 'since' => since }));
        result.jobClasses = IntegrationHubData.query('SELECT Id, Name FROM ApexClass WHERE Name IN :names ORDER BY Name',
            new Map<String, Object>{ 'names' => JOB_CLASSES });
        result.jobs = counts(IntegrationHubData.query('SELECT ApexClassId k, Status st, COUNT(Id) n, MAX(CompletedDate) lastAt '
            + 'FROM AsyncApexJob WHERE ApexClassId IN :ids AND CreatedDate >= :since AND JobType != :worker '
            + 'GROUP BY ApexClassId, Status', new Map<String, Object>{ 'ids' => new Map<Id, SObject>(result.jobClasses).keySet(),
            'since' => since, 'worker' => 'BatchApexWorker' }));
        result.objects = objects();
        return result;
    }

    /* Classes that implement the hub's interfaces; an empty list when the org cannot list them. */
    private static List<SObject> implementers() {
        try {
            return IntegrationHubData.query('SELECT ClassName, InterfaceName FROM ApexTypeImplementor '
                + 'WHERE InterfaceName IN :names AND IsConcrete = true AND ClassNamespacePrefix = null LIMIT 1000',
                new Map<String, Object>{ 'names' => INTERFACES });
        } catch (QueryException e) {
            return new List<SObject>();
        }
    }

    /**
     * @description Event keys written as text in IntegrationHub.publish('KEY', ...) calls, each once, in order. A key
     * passed in a variable is not a literal and is not returned.
     * @param body Apex code
     * @return the keys
     */
    @TestVisible
    private static List<String> eventKeys(String body) {
        List<String> keys = new List<String>();
        Integer at = String.isBlank(body) ? -1 : body.indexOfIgnoreCase(PUBLISH);
        while (at >= 0) {
            Matcher m = KEY_LITERAL.matcher(body.substring(at, Math.min(body.length(), at + SNIPPET)));
            if (m.find() && !keys.contains(m.group(1).trim())) {
                keys.add(m.group(1).trim());
            }
            at = body.indexOfIgnoreCase(PUBLISH, at + PUBLISH.length());
        }
        return keys;
    }

    /**
     * @description True for a test class: its code has the IsTest annotation (any case), or its code is hidden and its name ends with Test.
     * @param name class name
     * @param body class code
     * @return whether it is a test class
     */
    @TestVisible
    private static Boolean isTestClass(String name, String body) {
        return String.isBlank(body) || body == HIDDEN_BODY ? name.endsWithIgnoreCase('Test') : body.containsIgnoreCase(TEST_MARK);
    }

    /**
     * @description Class names typed on the events and connections and the implementers, as the tests are searched
     * for them.
     * @param result the scan with its events, connections and implementers
     * @return the names
     */
    @TestVisible
    private static Set<String> pluginNames(Scan result) {
        Set<String> names = new Set<String>();
        for (IH_Event__c ev : result.events) {
            names.addAll(new List<String>{ ev.Payload_Class__c, ev.Response_Handler_Class__c, ev.Handler_Class__c });
        }
        for (IH_Connection__c conn : result.connections) {
            names.add(conn.Auth_Class__c);
        }
        for (SObject imp : result.implementers) {
            names.add((String) imp.get('ClassName'));
        }
        names.remove(null);
        names.remove('');
        return names;
    }

    private static List<CountRow> counts(List<SObject> rows) {
        List<CountRow> out = new List<CountRow>();
        for (SObject row : rows) {
            CountRow c = new CountRow();
            c.key = String.valueOf(row.get('k'));
            c.status = (String) row.get('st');
            c.count = (Integer) row.get('n');
            c.lastAt = (Datetime) row.get('lastAt');
            out.add(c);
        }
        return out;
    }

    private static List<ObjectRow> objects() {
        List<ObjectRow> out = new List<ObjectRow>();
        for (Schema.DescribeSObjectResult d : Schema.describeSObjects(OBJECTS, SObjectDescribeOptions.DEFERRED)) {
            ObjectRow row = new ObjectRow();
            row.name = d.getName();
            // field map keys are lower-case API names: every custom field ends with __c, once
            row.customFields = String.join(new List<String>(d.fields.getMap().keySet()), ' ').countMatches('__c');
            out.add(row);
        }
        return out;
    }

    /**
     * @description Reads class and trigger code in system mode, chunk by chunk in SOQL for-loops; keeps names and numbers.
     */
    private without sharing class Elevated {
        private final Set<String> names;
        private final List<CodeRow> rows = new List<CodeRow>();

        Elevated(Set<String> pluginNames) {
            names = pluginNames;
        }

        List<CodeRow> scanCode() {
            String framework = 'IntegrationHub%';
            String prefixed = 'IH\\_%';
            for (ApexClass c : [SELECT Name, Body, LengthWithoutComments FROM ApexClass
                    WHERE NamespacePrefix = null OR Name LIKE :framework OR Name LIKE :prefixed
                    WITH SYSTEM_MODE ORDER BY Name]) {
                read(KIND_CLASS, c.Name, c.LengthWithoutComments).fill(c.Body, names);
            }
            for (ApexTrigger t : [SELECT Name, Body, LengthWithoutComments FROM ApexTrigger
                    WHERE NamespacePrefix = null WITH SYSTEM_MODE ORDER BY Name]) {
                read(KIND_TRIGGER, t.Name, t.LengthWithoutComments).fill(t.Body, names);
            }
            return rows;
        }

        private Reader read(String kind, String name, Integer chars) {
            CodeRow row = new CodeRow();
            row.kind = kind;
            row.name = name;
            row.chars = chars == null ? 0 : Math.max(chars, 0);
            rows.add(row);
            return new Reader(row);
        }
    }

    /**
     * @description Fills one code row from its code.
     */
    private class Reader {
        private final CodeRow row;

        Reader(CodeRow codeRow) {
            row = codeRow;
        }

        void fill(String body, Set<String> pluginNames) {
            row.isTest = row.kind == KIND_CLASS && isTestClass(row.name, body);
            row.publishes = !row.isTest && body != null && body.containsIgnoreCase(PUBLISH);
            row.keys = row.publishes ? eventKeys(body) : row.keys;
            if (row.isTest && body != null) {
                for (String name : pluginNames) {
                    addMention(name, body);
                }
            }
        }

        private void addMention(String name, String body) {
            if (!name.substringBefore('.').equalsIgnoreCase(row.name) && body.containsIgnoreCase(name)) {
                row.mentions.add(name);
            }
        }
    }
}
